"""Build the human-readable run report from audited evidence, without inference."""
import collections
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
run=ROOT/'data/training/lora-v1'
training=json.loads((run/'training-result.json').read_text())
loss=json.loads((run/'loss-review.json').read_text())
merge=json.loads((run/'merged-manifest.json').read_text())
smoke=json.loads((run/'merged-smoke.json').read_text())
comparison=json.loads((run/'comparison.json').read_text())
r=comparison['reports']
labels=list(r['merged_raw']['per_class'])
lines=['# One bounded LoRA run — November 6, 2026','','One actual offline LoRA run completed, followed by loss review, standalone merge,','five predeclared smoke cases and full matched development evaluation. No reserved','final manifest was opened and no final predictions were produced. Curator’s','Studio was not used. No prompt/configuration sweep or best-checkpoint search ran.','','## Run and data evidence','',f"- Final checkpoint: 600 optimizer updates, batch size 4, constant Adam learning",'  rate 0.0001; seed 0; no gradient accumulation or class reweighting.',f"- {training['training_exposures']:,} exposures, all distinct, from 11,430 available training rows",f"  ({training['training_exposures']/11430:.2%} of train, a partial pass rather than a full epoch).",'- Rank 8, native MLX scale 20, dropout 0; q_proj/v_proj in the last 16 layers.',f"  {training['trainable_parameters']:,} trainable parameters. Only LoRA tensors were trainable.",'- All frozen base tensor hashes were unchanged after training. Base revision:',f"  `{training['base_revision']}`.",f"- Training took {training['seconds']:.1f} seconds; peak MLX memory {training['peak_memory_gb']:.2f} GB.",'- Raw prompt is identical to the saved base diagnostic. Supervise the full exact', '  label plus EOS 151643; no chat template, prompt loss, padding loss or truncation.', '  Maximum training sequence was 509 tokens; maximum development sequence 486.', '- The standard MLX completion dataset would apply a chat template. This run uses', '  an explicit pretokenized dataset and completion loss to preserve the raw', '  contract. The mask targets original positions >=prompt_length and', '  <sequence_length. Actual-batch checks and a padding-invariance test passed.', '', '| Training reference class | Actual examples seen |','| --- | ---: |']
for c in labels:lines.append(f"| {c} | {training['training_exposure_class_counts'][c]} |")
lines += ['', 'The predeclared configuration, source/split hashes, batch-mask audit, monitor IDs,', 'actual exposure IDs, loss log and frozen-base hashes are in `data/training/lora-v1/`.', 'The final adapter is ignored at `runtime/lora-v1/adapters.safetensors`:', f"`{training['adapter_sha256']}`.", '', '## Loss review', '', f"Training 20-update mean: {loss['training_first_20_step_mean']:.6f} initially to", f"{loss['training_last_20_step_mean']:.6f} for the last 20 updates. Fixed-monitor loss:", f"{loss['initial_monitor_loss']:.6f} before training to {loss['final600_monitor_loss']:.6f}", f"after reloading final600. Lowest logged monitor loss was {loss['best_logged_monitor_loss']:.6f}", f"at completed update 499; final loss is {loss['final_minus_best_logged_monitor']:.6f} higher.", '', 'The curve decreases overall but fluctuates and rebounds from its minimum.', 'It does not show monotonic improvement or establish that more training would', 'help. The final600 checkpoint was selected before training and retained.', 'The monitor contains 40 development reports per class (240 total), selected by', 'SHA-256 of event ID before predictions. It is label-balanced, not full-population', 'development loss. Loss is per supervised label/EOS token; training points average', '20 changing minibatches. These are teacher-forced losses, not classification', 'accuracy. Training callback validation points 0,99,...599 occur before the next', 'update; a separate final600 measurement uses the saved adapter.', '', '![Recorded training and development-monitor losses](../data/training/lora-v1/loss-curve.png)', '', '## Standalone merge and smoke tests', '', f"Native MLX fusion folded {merge['fused_linear_layers']} adapted linear layers into BF16 base weights.", 'No quantization, GGUF conversion, upload or hosted inference occurred. The', 'standalone artifact is `runtime/merged-lora-v1/`; file hashes are in', '`merged-manifest.json`. It has 1,720,574,976 parameters, no adapter configuration', 'dependency and retains the upstream Apache 2.0 license and attribution.', 'Saved-tokenizer parity passed for both protocols on all 2,449 development rows.', '', f"The actual saved/reloaded merged artifact passed {smoke['passed']}/5 smoke cases before full", 'classification evaluation. These cover five of six classes; they are a sanity', 'check, not an input-coverage or out-of-scope evaluation.', '', '| Expected | Actual merged output | Result |','| --- | --- | --- |']
for case in smoke['cases']:lines.append(f"| {case['expected']} | {case['prediction']} | {'Pass' if case['correct'] else 'Fail'} |")
lines += ['', '## Matched development results', '', 'All methods below use the identical 2,449 frozen development IDs, reference', 'labels and order. Accuracy, macro-F1, class precision/recall/F1/support and', 'confusion matrices were independently recomputed from saved predictions.', 'Invalid completions count as incorrect. Reference labels were never changed.', '', '| Method | Accuracy | Macro-F1 | Invalid |','| --- | ---: | ---: | ---: |']
for key,label in [('keyword','Keyword'),('base_raw','Base raw completion'),('adapter_raw','Attached adapter raw'),('merged_raw','Reloaded merged raw'),('base_letter','Base handout letter'),('adapter_letter','Attached adapter letter'),('merged_letter','Reloaded merged letter')]:
    m=r[key];lines.append(f"| {label} | {m['accuracy']:.2%} | {m['macro_f1']:.2%} | {m['invalid_count']} |")
d=comparison['matched_deltas']['merged_raw']
lines += ['',f"Merged raw accuracy changes: {100*d['accuracy_vs_matched_base']:+.2f} percentage points versus",f"matched base raw; {100*d['accuracy_vs_keyword']:+.2f} points versus keyword. Macro-F1 changes",f"{100*d['macro_f1_vs_matched_base']:+.2f} points versus matched base raw.", '', 'The raw protocol is unchanged: raw prompt, greedy 16-token budget, EOS stop,', 'exact full-label parser, batch size 8. The separate letter protocol preserves', 'the handout first-step constrained A–F scoring, same chat prompt and same single', 'letter IDs for every artifact. The model was trained for raw completion, so a', 'letter-protocol regression must be reported, not hidden. Cross-format deltas', 'do not isolate training gains. The weak base-letter score is not the sole', 'benchmark; the stronger keyword and base-raw results remain visible.', '', '![Matched development comparison](../data/training/lora-v1/development-comparison.png)', '', '### Merged raw per-class report', '', '| Reference | Precision | Recall | F1 | Support | F1 delta vs base raw | F1 delta vs keyword |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for c in labels:
    m=r['merged_raw']['per_class'][c]
    lines.append(f"| {c} | {m['precision']:.2%} | {m['recall']:.2%} | {m['f1']:.2%} | {m['support']} | {100*d['per_class_f1_vs_matched_base'][c]:+.2f} pp | {100*d['per_class_f1_vs_keyword'][c]:+.2f} pp |")
lines += ['', 'Full per-class reports and confusion matrices for every artifact/protocol are', 'in `data/evaluations/*-lora-v1-*/metrics.json`; the audited combined report is', '`data/training/lora-v1/comparison.json`. Rows are references and columns are', 'predictions, with a separate INVALID column.', '', '![Matched raw confusion matrices](../data/training/lora-v1/confusion-matrices.png)', '', '### Largest merged raw confusions', '']
errors=collections.Counter({(t,p):n for t,row in r['merged_raw']['confusion_matrix'].items() for p,n in row.items() if p!=t and n})
for (t,p),n in errors.most_common(6):lines.append(f'- {t} → {p}: {n} {"report" if n == 1 else "reports"}.')
lines += ['', 'Qualitative spot review of six adapter errors is recorded in `error-review.json`.', 'Examples include an EF-0 report missed as Wind, damage-only Tornado narratives,', 'a snow-squall report dominated by wind measurements, a combined hail/wind report,', 'and source Wind event 1211898 whose narrative describes a landspout. This is', 'diagnostic review, not relabeling. Human unresolved/correction support remains', 'necessary; reference-label accuracy is not semantic certainty.', '', '### Metric regressions versus matched base', '',
'The following decreases remain visible even when aggregate accuracy or class',
'F1 improves. Scores are closed-set reference-label measurements, not calibrated',
'confidence. No second run or threshold change was triggered.', '',
'| Protocol | Class | Metric | Base | Merged | Change |',
'| --- | --- | --- | ---: | ---: | ---: |']
for protocol in ('raw','letter'):
    for c in labels:
        for metric in ('precision','recall','f1'):
            before=r['base_'+protocol]['per_class'][c][metric]
            after=r['merged_'+protocol]['per_class'][c][metric]
            if after < before-1e-12:
                lines.append(f"| {protocol} | {c} | {metric} | {before:.2%} | {after:.2%} | {100*(after-before):+.2f} pp |")
lines += ['', '## Merge drift', '']
for protocol in ['raw','letter']:
    drift=comparison['merge_drift'][protocol]
    lines.append(f"- {protocol}: {drift['prediction_disagreements']} adapter/merged label disagreements; agreement {drift['agreement']:.4%}.")
    if protocol=='raw':lines.append(f"  Raw completion strings differ on {drift['raw_completion_differences']} rows; token sequences on {drift['token_sequence_differences']} rows.")
    else:lines.append(f"  Choice-logit absolute drift: max {drift['choice_logit_max_absolute_difference']:.6f}, mean {drift['choice_logit_mean_absolute_difference']:.6f}.")
lines += ['', 'Native fusion casts the low-rank delta to BF16 before adding it to BF16 base', 'weights. Attached inference and fused inference need not be numerically', 'identical. The comparison records every label disagreement by event ID instead', 'of assuming merge equivalence. No quantization was used.', '', '## Reproduce and continue', '', 'Use the isolated `.venv` and pinned base/environment from `LOCAL_MODEL_SETUP.md`.', 'Create the separate plotting environment if needed:', '', '```sh', 'UV_CACHE_DIR="$PWD/work/uv-cache" uv venv --python .venv/bin/python work/plot-env', 'UV_CACHE_DIR="$PWD/work/uv-cache" uv pip install --python work/plot-env/bin/python -r requirements-plot.lock', '```', '', 'The original first-run sequence was:', '', '```sh', '.venv/bin/python scripts/train_lora.py', '.venv/bin/python scripts/review_lora_loss.py', 'work/plot-env/bin/python scripts/plot_lora_loss.py', '.venv/bin/python scripts/merge_lora.py', '.venv/bin/python scripts/evaluate_lora.py --artifact merged --smoke', '.venv/bin/python scripts/run_matched_lora_evaluation.py', 'work/plot-env/bin/python scripts/plot_lora_evaluation.py', '.venv/bin/python scripts/write_lora_report.py', '.venv/bin/python scripts/audit_lora_evidence.py', '```', '', 'Preserve existing v1 evidence: training/merge/completed evaluation refuse', 'overwrite; the evaluation driver preserves completed stages and validates their', 'hashes. Do not launch another run simply to regenerate a document. Plotting uses', 'a separate ignored environment pinned in `requirements-plot.lock`; it does not', 'change the model environment. All model stages are offline and local.', '', 'This completes the local training/merge/development milestone, not the full', 'submission or a model deployment decision. The user explicitly accepted the', 'local MLX/custom-data adaptation to the handout; no LLaMA Board execution is', 'claimed. Remaining work: one human-review application workflow, evaluation of', 'the actual served artifact, dataset/code/model attribution and reproducibility', 'assets, GitHub publication and Loom demonstration. Keep the reserved final', 'untouched until a separately predeclared final evaluation is authorized.', '', 'Dataset limits remain: one year, uncertain label/text alignment, class imbalance,', 'same-label duplicates, row-weighted evaluation, unknown upstream pretraining', 'overlap, and only 41 development Wildfire reports. Closed-set scores and five', 'smoke cases do not establish confidence calibration or arbitrary-input coverage.', '']
(ROOT/'docs/LORA_RUN.md').write_text('\n'.join(lines))
print('Saved docs/LORA_RUN.md')
